// Two unevenly spaced combustion pulses per cycle, with low exhaust resonance.
export function makeV2Loop(sampleRate=48000){const cycle=.16,cycles=16,samples=new Float32Array(Math.round(sampleRate*cycle*cycles));let seed=71;const events=[];for(let i=0;i<cycles;i++){events.push(i*cycle,i*cycle+cycle*.6);}for(const start of events){for(let n=0;n<sampleRate*.12;n++){const index=(Math.round(start*sampleRate)+n)%samples.length;const t=n/sampleRate;seed=(seed*1664525+1013904223)>>>0;const noise=(seed/4294967296-.5)*2;const attack=Math.min(1,t/.0015),decay=Math.exp(-t*38);const thump=Math.sin(2*Math.PI*(51*t-65*t*t))+.34*Math.sin(2*Math.PI*103*t)+noise*.16*Math.exp(-t*50);samples[index]+=Math.tanh(thump*1.55)*decay*attack*.66;}}return samples;}
export function makeEngineLoop(kind='v2',sampleRate=48000){if(kind==='v2')return makeV2Loop(sampleRate);const duration=kind==='electric'?.64:2.56,b=new Float32Array(Math.round(sampleRate*duration));for(let i=0;i<b.length;i++){const t=i/sampleRate;if(kind==='electric')b[i]=.22*(Math.sin(2*Math.PI*125*t)+.2*Math.sin(2*Math.PI*250*t)+.08*Math.sin(2*Math.PI*1000*t));else{const pulse=(t%(.04))/.04;b[i]=.48*Math.tanh((Math.sin(2*Math.PI*100*t)+.4*Math.sin(2*Math.PI*200*t))*2)*Math.exp(-pulse*3);}}return b;}
export function createV2Audio(sound){const ctx=new(window.AudioContext||window.webkitAudioContext)(),master=ctx.createGain(),gain=ctx.createGain(),filter=ctx.createBiquadFilter(),resonance=ctx.createBiquadFilter();master.gain.value=sound?.58:0;master.connect(ctx.destination);gain.gain.value=0;gain.connect(master);filter.type='lowpass';filter.frequency.value=780;filter.Q.value=.65;resonance.type='peaking';resonance.frequency.value=112;resonance.Q.value=.8;resonance.gain.value=4;const source=ctx.createBufferSource(),samples=makeV2Loop(ctx.sampleRate),buffer=ctx.createBuffer(1,samples.length,ctx.sampleRate);buffer.copyToChannel(samples,0);source.buffer=buffer;source.loop=true;const dc=ctx.createBiquadFilter();dc.type='highpass';dc.frequency.value=26;source.connect(dc);dc.connect(filter);filter.connect(resonance);resonance.connect(gain);source.start();const engineSources=[source],engineGains=[];const base=ctx.createGain();base.gain.value=1;source.disconnect();source.connect(base);base.connect(dc);engineGains.push(base);for(const kind of ['race','electric']){const s=ctx.createBufferSource(),g=ctx.createGain(),values=makeEngineLoop(kind,ctx.sampleRate),b=ctx.createBuffer(1,values.length,ctx.sampleRate);b.copyToChannel(values,0);s.buffer=b;s.loop=true;g.gain.value=0;s.connect(g);g.connect(dc);s.start();engineSources.push(s);engineGains.push(g);}const voiceGain=ctx.createGain();voiceGain.connect(master);return {ctx,master,gain,filter,source,engineSources,engineGains,voiceGain};}
export function updateV2Audio(audio,{sound,driving,speed,throttle,boost,engineVolume=1,engineSound='v2',voiceVolume=1}){const t=audio.ctx.currentTime;audio.master.gain.setTargetAtTime(sound?.58:0,t,.06);audio.gain.gain.setTargetAtTime(driving?engineVolume*(throttle?.32:.2)*(audio.voiceUntil>t?.28:1):0,t,.06);const rate=.78+Math.max(0,speed)*.059+(throttle?.22:0)+(boost?.25:0);audio.engineSources.forEach((s,i)=>{s.playbackRate.setTargetAtTime(i===2?.7+speed*.018:rate,t,.09);audio.engineGains[i].gain.setTargetAtTime(i===['v2','race','electric'].indexOf(engineSound)?1:0,t,.06);});audio.voiceGain.gain.setTargetAtTime(voiceVolume,t,.04);audio.filter.frequency.setTargetAtTime(700+speed*24+(throttle?250:0),t,.1);}
